1	import assert from 'node:assert/strict';
2	import { spawn, spawnSync } from 'node:child_process';
3	import fs from 'node:fs';
4	import os from 'node:os';
5	import path from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	import { after } from 'node:test';
8	
9	export const CLI = fileURLToPath(new URL('../jsonpatch-cli.mjs', import.meta.url));
10	export const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
11	export const LIMIT = 1048576;
12	export const BOM = Buffer.from([0xef, 0xbb, 0xbf]);
13	
14	export function run(args, { input, stdinFd, cwd, timeout = 60000 } = {}) {
15	  const opts = {
16	    cwd,
17	    timeout,
18	    maxBuffer: 64 * 1024 * 1024,
19	    encoding: 'utf8',
20	  };
21	  if (stdinFd !== undefined) {
22	    opts.stdio = [stdinFd, 'pipe', 'pipe'];
23	  } else {
24	    opts.input = input === undefined ? '' : input;
25	  }
26	  const r = spawnSync(process.execPath, [CLI, ...args], opts);
27	  return { status: r.status, stdout: r.stdout, stderr: r.stderr };
28	}
29	
30	// Async run. With stdinOpen the stdin pipe is never written or ended, so a CLI that
31	// reads stdin too early hangs until timeoutMs, then is killed and timedOut is true.
32	export function runAsync(args, { stdinOpen = false, timeoutMs = 10000 } = {}) {
33	  return new Promise((resolve, reject) => {
34	    const child = spawn(process.execPath, [CLI, ...args], { stdio: ['pipe', 'pipe', 'pipe'] });
35	    let stdout = '';
36	    let stderr = '';
37	    let timedOut = false;
38	    child.stdout.setEncoding('utf8').on('data', (c) => { stdout += c; });
39	    child.stderr.setEncoding('utf8').on('data', (c) => { stderr += c; });
40	    const timer = setTimeout(() => {
41	      timedOut = true;
42	      child.kill('SIGKILL');
43	    }, timeoutMs);
44	    child.on('error', (err) => {
45	      clearTimeout(timer);
46	      reject(err);
47	    });
48	    child.on('close', (status) => {
49	      clearTimeout(timer);
50	      resolve({ status, stdout, stderr, timedOut });
51	    });
52	    if (!stdinOpen) child.stdin.end();
53	    // Nothing is written; an EPIPE after the child exits is expected and harmless.
54	    else child.stdin.on('error', (err) => { if (err.code !== 'EPIPE') reject(err); });
55	  });
56	}
