58	// Creates a temp dir and registers cleanup for the calling suite.
59	export function tempDir() {
60	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'jsonpatch-cli-'));
61	  after(() => {
62	    fs.rmSync(dir, { recursive: true, force: true });
63	  });
64	  return dir;
65	}
