73	export function assertFailure(r, exitCode, line) {
74	  assert.equal(r.status, exitCode);
75	  assert.equal(r.stdout, '');
76	  assert.equal(r.stderr, line + '\n');
77	}
78	
79	export function assertSuccess(r, value) {
80	  assert.equal(r.status, 0);
81	  assert.equal(r.stderr, '');
82	  assert.equal(r.stdout, JSON.stringify(value, null, 2) + '\n');
83	}
