85	// Valid JSON '[]' padded with trailing spaces so that prefix + content is `total` bytes.
86	export function padded(total, prefix = Buffer.alloc(0)) {
87	  const body = Buffer.from('[]');
88	  const fill = Buffer.alloc(total - prefix.length - body.length, 0x20);
89	  return Buffer.concat([prefix, body, fill]);
90	}
