52	  const cases = [
53	    ['~01 decodes to the two characters ~1 (not to a slash)', '/~01', ['~1']],
54	    ['~10 decodes to a slash followed by 0 (not to a tilde)', '/~10', ['/0']],
55	    ['~0~1 decodes to tilde then slash', '/~0~1', ['~/']],
56	    ['~1~0 decodes to slash then tilde', '/~1~0', ['/~']],
57	    ['~00 decodes to tilde followed by 0', '/~00', ['~0']],
58	    ['~11 decodes to slash followed by 1', '/~11', ['/1']],
59	    ['~0 alone decodes to a tilde', '/~0', ['~']],
60	    ['~1 alone decodes to a slash and does not split', '/~1', ['/']],
61	    ['escapes inside several tokens', '/a~1b/c~0d', ['a/b', 'c~d']],
62	    ['an escape followed by a separator', '/~1/~0', ['/', '~']],
63	    ['a tilde escape at token end followed by empty token', '/~0/', ['~', '']],
