26	describe('patch must be an array', () => {
27	  const cases = [
28	    ['undefined', undefined],
29	    ['null', null],
30	    ['a plain object', {}],
31	    ['a string "[]"', '[]'],
32	    ['the number 0', 0],
33	    ['an array-like with length 0', { length: 0 }],
34	    ['a Uint8Array', new Uint8Array(0)],
35	    ['an arguments-like object', { 0: { op: 'test', path: '', value: 1 }, length: 1 }],
36	    ['true', true],
37	    ['a function', () => []],
38	  ];
39	  for (const [name, patch] of cases) {
40	    test(`${name} gives "patch must be an array" with index null`, () => {
41	      assertPatchError({ a: 1 }, patch, 'patch must be an array', null);
42	    });
43	  }
44	
45	  test('an empty array is fine and returns a copy of the document', () => {
46	    const doc = { a: [1, { b: -0 }] };
47	    const result = applyPatch(doc, []);
48	    assertExact(result, { a: [1, { b: -0 }] });
49	    assertNoSharing(result, doc);
50	  });
