152	describe('bad op', () => {
153	  const base = { path: '/a', value: 1 };
154	  const cases = [
155	    ['missing', { ...base }],
156	    ['null', { op: null, ...base }],
157	    ['undefined', { op: undefined, ...base }],
158	    ['upper case ADD', { op: 'ADD', ...base }],
159	    ['trailing space "add "', { op: 'add ', ...base }],
160	    ['capitalised Add', { op: 'Add', ...base }],
161	    ['a String object', { op: new String('add'), ...base }],
162	    ['an array', { op: ['add'], ...base }],
163	    ['a number', { op: 1, ...base }],
164	    ['an unknown name', { op: 'merge', ...base }],
165	    ['the empty string', { op: '', ...base }],
166	    ['inherited from the prototype', Object.create({ op: 'add', path: '/a', value: 1 })],
167	    ['inherited op with own path and value', Object.assign(Object.create({ op: 'add' }), base)],
168	  ];
169	  for (const [name, bad] of cases) {
170	    test(`op ${name} gives "bad op"`, () => assertFormError(bad, 'bad op'));
171	  }
172	
173	  test('a non-enumerable own op counts as present', () => {
174	    assertExact(applyPatch({}, [hidden({ op: 'add', ...base }, 'op', 'add')]), { a: 1 });
175	  });
176	});
177	
178	describe('bad path', () => {
179	  const cases = [
180	    ['missing', { op: 'add', value: 1 }],
181	    ['null', { op: 'add', path: null, value: 1 }],
182	    ['a number', { op: 'add', path: 5, value: 1 }],
183	    ['a String object', { op: 'add', path: new String('/a'), value: 1 }],
184	    ['not starting with a slash', { op: 'add', path: 'a', value: 1 }],
185	    ['containing a bad escape', { op: 'add', path: '/~2', value: 1 }],
186	    ['an array', { op: 'add', path: ['/a'], value: 1 }],
187	    ['inherited', Object.assign(Object.create({ path: '/a' }), { op: 'add', value: 1 })],
188	    ['bad on remove', { op: 'remove', path: 'x' }],
189	    ['bad on replace', { op: 'replace', path: '~', value: 1 }],
190	    ['bad on test', { op: 'test', path: '#/a', value: 1 }],
191	    ['bad on move', { op: 'move', path: 'a', from: '/a' }],
192	    ['bad on copy', { op: 'copy', path: ' /a', from: '/a' }],
193	  ];
194	  for (const [name, bad] of cases) {
195	    test(`path ${name} gives "bad path"`, () => assertFormError(bad, 'bad path'));
196	  }
