1	// Runs the test suite against each near-miss mutant and reports KILLED or SURVIVED.
2	import crypto from 'node:crypto';
3	import fs from 'node:fs';
4	import os from 'node:os';
5	import path from 'node:path';
6	import { spawnSync } from 'node:child_process';
7	import { fileURLToPath } from 'node:url';
8	
9	const HERE = path.dirname(fileURLToPath(import.meta.url));
10	const ROOT = path.resolve(HERE, '..', '..');
11	const TARGETS = ['jsonpatch.mjs', 'jsonpatch-cli.mjs'];
12	const NAME_RE = /^\d+-(jsonpatch(?:-cli)?\.mjs)$/;
13	
14	function sha256(file) {
15	  return crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
16	}
17	
18	function snapshotOriginals() {
19	  const backup = fs.mkdtempSync(path.join(os.tmpdir(), 'jp-nm-'));
20	  const hashes = {};
21	  for (const target of TARGETS) {
22	    hashes[target] = sha256(path.join(ROOT, target));
23	    fs.copyFileSync(path.join(ROOT, target), path.join(backup, target));
24	  }
25	  return { backup, hashes };
26	}
27	
28	function restoreAll(backup) {
29	  for (const target of TARGETS) {
30	    fs.copyFileSync(path.join(backup, target), path.join(ROOT, target));
31	  }
32	}
33	
34	function listCopies(prefixes) {
35	  return fs
36	    .readdirSync(HERE)
37	    .filter((name) => NAME_RE.test(name))
38	    .filter((name) => prefixes.length === 0 || prefixes.some((p) => name.startsWith(p)))
39	    .sort();
40	}
41	
42	function describeCopy(file) {
43	  const first = fs.readFileSync(path.join(HERE, file), 'utf8').split('\n', 1)[0];
44	  return first.replace(/^\/\/ near-miss: /, '');
45	}
46	
47	function runTests() {
48	  return spawnSync(process.execPath, ['--test', 'test/*.test.mjs'], {
49	    cwd: ROOT,
50	    encoding: 'utf8',
51	    maxBuffer: 256 * 1024 * 1024,
52	    timeout: 300000,
53	  });
54	}
55	
56	function failCount(result) {
57	  const match = /^# fail (\d+)/m.exec(result.stdout || '');
58	  return match ? match[1] : '?';
59	}
60	
61	function runOne(file, backup) {
62	  const target = NAME_RE.exec(file)[1];
63	  try {
64	    fs.copyFileSync(path.join(HERE, file), path.join(ROOT, target));
65	    const result = runTests();
66	    const timedOut = result.error?.code === 'ETIMEDOUT';
67	    if (result.error && !timedOut) throw result.error;
68	    return { survived: !timedOut && result.status === 0, timedOut, fails: failCount(result) };
69	  } finally {
70	    restoreAll(backup);
71	  }
72	}
73	
74	function label({ survived, timedOut }) {
75	  if (timedOut) return 'TIMEOUT';
76	  return survived ? 'SURVIVED' : 'KILLED';
77	}
78	
79	function runAll(backup) {
80	  let survivors = 0;
81	  for (const file of listCopies(process.argv.slice(2))) {
82	    const outcome = runOne(file, backup);
83	    if (outcome.survived) survivors++;
84	    process.stdout.write(`${label(outcome)} ${file} — ${describeCopy(file)} (fail ${outcome.fails})\n`);
85	  }
86	  return survivors;
87	}
88	
89	function main() {
90	  const { backup, hashes } = snapshotOriginals();
91	  const onSignal = () => {
92	    restoreAll(backup);
93	    process.exit(130);
94	  };
95	  process.on('SIGINT', onSignal);
96	  process.on('SIGTERM', onSignal);
97	
98	  let survivors;
99	  try {
100	    survivors = runAll(backup);
101	  } catch (err) {
102	    fs.rmSync(backup, { recursive: true, force: true });
103	    process.stderr.write(`error: ${err.message}\n`);
104	    process.exit(2);
105	  }
106	
107	  const intact = TARGETS.every((t) => sha256(path.join(ROOT, t)) === hashes[t]);
108	  if (!intact) {
109	    process.stderr.write('ERROR: originals changed\n');
110	    process.exit(2);
111	  }
112	  fs.rmSync(backup, { recursive: true, force: true });
113	  process.stdout.write('originals intact\n');
114	  process.stdout.write(`survivors: ${survivors}\n`);
115	  process.exit(survivors > 0 ? 1 : 0);
116	}
117	
118	main();
